  const data = cv.toDataURL("image/jpeg", .85); img.src = data; URL.revokeObjectURL(url); pg.querySelector(".zht-demo") && pg.querySelector(".zht-demo").remove();
  const OCR = window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.HVOcr;
  if (!OCR){ found.innerHTML = `<div class="zht-note">${T("camApp")}</div>`; return; }
  found.innerHTML = `<div class="zht-note">${T("reading")}</div>`;
