    const ph = pg.querySelector(".zht-photo"); W.forEach(b=>{ const d = document.createElement("div"); d.className = "zht-box"; d.dataset.zbox = b.w; d.style.cssText = `left:${b.x * 100}%;top:${b.y * 100}%;width:${b.ww * 100}%;height:${b.hh * 100}%`; ph.appendChild(d); });
