let DICT = null, MEAN = null;
function dict(){ if (DICT) return DICT; DICT = new Map(); DICT_SRC.split("\n").forEach(l=>{ const i = l.indexOf(" "); if (i > 0) DICT.set(l.slice(0, i), l.slice(i + 1)); });
  MEAN = new Map(); MEAN_SRC.split("\n").forEach(l=>{ const i = l.indexOf("\t"); if (i > 0) MEAN.set(l.slice(0, i), l.slice(i + 1)); }); return DICT; }
const lastC = c => c.replace(/[12]/g, "").slice(-1);
const plural = c => "szSZCJ".includes(lastC(c)) ? c + "iz" : "ptkfT".includes(lastC(c)) ? c + "s" : c + "z";
const past = c => "td".includes(lastC(c)) ? c + "id" : "pkfTsSC".includes(lastC(c)) ? c + "t" : c + "d";
// 查一个词；表里没有的变形（复数、过去式、-ing）照规则推
function look(w){ w = String(w).toLowerCase().replace(/’/g, "'"); const D = dict(); if (D.has(w)) return D.get(w);
  const first = L => { for (const b of L) if (b.length > 1 && D.has(b)) return D.get(b); return null; };
  let c;
  if (w.endsWith("'s") && (c = first([w.slice(0, -2)]))) return plural(c);
  if (w.endsWith("ing") && (c = first([w.slice(0, -3), w.slice(0, -3) + "e", w.slice(0, -4)]))) return c + "iN";
  if (w.endsWith("ed") && (c = first([w.slice(0, -2), w.slice(0, -1), w.slice(0, -3), w.slice(0, -3) + "y"]))) return past(c);
  if (w.endsWith("s") && (c = first([w.slice(0, -1), w.slice(0, -2), w.slice(0, -3) + "y"]))) return plural(c);
  return null; }
const ONS = new Set("pl pr bl br tr dr kl kr gl gr fl fr Tr Sr sp st sk sm sn sl sw tw dw kw gw spl spr str skr skw".split(" "));
const legal = a => a.length <= 1 ? a[0] !== "N" : ONS.has(a.join("")) || a.length === 2 && a[1] === "y" && "pbfmkhvg".includes(a[0]) || a.length === 3 && a[0] === "s" && a[2] === "y" && "pk".includes(a[1]);
// 切成音节：两个元音之间的辅音，能当开头的尽量归后一个音节
function syls(code){ const tk = [...code.matchAll(/([a-zA-Z@^])([12]?)/g)].map(m=>({c: m[1], s: +m[2] || 0})), V = []; tk.forEach((t, i)=>{ if (VOW.has(t.c)) V.push(i); });
  if (!V.length) return [{t: tk, s: 0}]; const out = []; let start = 0;
  V.forEach((vi, k)=>{ const nx = V[k + 1]; let end = tk.length; if (nx != null){ const cons = tk.slice(vi + 1, nx).map(t=>t.c); let cut = 0; while (cut < cons.length && !legal(cons.slice(cut))) cut++; end = vi + 1 + cut; }
    out.push({t: tk.slice(start, end), s: tk[vi].s}); start = end; });
  return out; }
const ipa1 = (t, end) => t.c === "^" ? (t.s ? "ʌ" : "ə") : t.c === "R" ? (t.s ? "ɜːr" : "ər") : t.c === "E" && !t.s && end ? "i" : PH[t.c][0];
function sylIpa(S){ return S.map((sy, k)=>sy.t.map((t, j)=>ipa1(t, k === S.length - 1 && j === sy.t.length - 1)).join("")); }
function ipaOf(w){ const c = look(w); if (!c) return ""; const S = syls(c), A = sylIpa(S); return A.map((x, k)=>(S.length > 1 ? (S[k].s === 1 ? "ˈ" : S[k].s === 2 ? "ˌ" : "") : "") + x).join(""); }
